import os, copy
from fontTools.ttLib import TTFont
from fontTools.ttLib.scaleUpem import scale_upem
from fontTools.varLib.instancer import instantiateVariableFont
from fontTools import subset

ROOT='/home/kurian/git/ezhuthu'
BASE=os.path.join(ROOT,'sources','base')
ML_RANGES=[(0x0D00,0x0D7F)]

def load_manjari(weight=400):
    f=TTFont(os.path.join(BASE,'Manjari-Regular.ttf' if weight==400 else 'Manjari-Bold.ttf'))
    scale_upem(f,1000)
    for tag in ('prep','fpgm','cvt ','VDMX','hdmx','LTSH'):
        if tag in f: del f[tag]
    return f

def load_donor(name, weight=400):
    f=TTFont(os.path.join(BASE,name))
    instantiateVariableFont(f,{'wght':weight,'wdth':100},inplace=True)
    for tag in ('fvar','gvar','avar','STAT','HVAR','MVAR','VVAR','DSIG','prep','fpgm','cvt ','VDMX','hdmx','LTSH'):
        if tag in f: del f[tag]
    scale_upem(f,1000)
    return f

def closure(path, ranges):
    f=TTFont(path)
    opts=subset.Options(); opts.layout_features=['*']; opts.notdef_outline=True; opts.recalc_bounds=False; opts.drop_tables=[]
    s=subset.Subsetter(opts)
    cps={cp for t in f['cmap'].tables if t.isUnicode() for cp in t.cmap if any(lo<=cp<=hi for lo,hi in ranges)}
    s.populate(unicodes=cps); s.subset(f)
    return set(f.getGlyphOrder())

def unicode_cmap(f):
    out={}
    for t in f['cmap'].tables:
        if t.isUnicode():
            out.update(t.cmap)
    return out

def transplant(manjari, donor):
    ml=closure(os.path.join(BASE,'Manjari-Regular.ttf'),ML_RANGES)
    mg=manjari['glyf']; dg=donor['glyf']
    mh=manjari['hmtx']; dh=donor['hmtx']
    mcmap=unicode_cmap(manjari); dcmap=unicode_cmap(donor)
    dorder=list(donor.getGlyphOrder())
    dnames=set(dorder)
    added=[]
    copied=set()
    def copy_glyph(srcname, dstname):
        if dstname in copied: return
        copied.add(dstname)
        g=copy.deepcopy(mg[srcname])
        dg[dstname]=g
        dh.metrics[dstname]=mh.metrics[srcname]
        if dstname not in dnames:
            dorder.append(dstname); dnames.add(dstname); added.append(dstname)
        if g.isComposite():
            for comp in g.components:
                cn=comp.glyphName
                if cn in ml:
                    # a shared glyph may reference a script component; copy it
                    copy_glyph(cn, cn)
                elif cn in mg:
                    copy_glyph(cn, cn)
    # replace shared codepoints
    for cp, mgname in sorted(mcmap.items()):
        if any(lo<=cp<=hi for lo,hi in ML_RANGES): continue
        if mgname in ml: continue
        if cp in dcmap:
            copy_glyph(mgname, dcmap[cp])
        else:
            # append under the manjari name, or a unique name
            name=mgname if mgname not in dnames else f'kallar.{mgname}'
            copy_glyph(mgname, name)
    # copy .notdef and other essential glyphs
    for name in ('.notdef','.null','nonmarkingreturn'):
        if name in mg and name not in copied:
            copy_glyph(name, name)
    donor.setGlyphOrder(dorder)
    dg.glyphOrder=dorder
    donor['maxp'].numGlyphs=len(dorder)
    # update cmap: map manjari shared cps to donor name or appended name
    for t in manjari['cmap'].tables:
        if not t.isUnicode(): continue
        for cp,mgname in t.cmap.items():
            if any(lo<=cp<=hi for lo,hi in ML_RANGES) or mgname in ml: continue
            if cp in dcmap:
                gname=dcmap[cp]
            else:
                gname=mgname if mgname in dnames else f'kallar.{mgname}'
            for dt in donor['cmap'].tables:
                if dt.isUnicode() and dt.platformID==t.platformID and dt.platEncID==t.platEncID:
                    dt.cmap[cp]=gname
                    break
    return donor

if __name__=='__main__':
    for donor_name,out in [('NotoSansDevanagari-VF.ttf','/tmp/opencode/merged_deva.ttf'),('NotoSansTamil-VF.ttf','/tmp/opencode/merged_taml.ttf')]:
        m=load_manjari(400); d=load_donor(donor_name,400)
        transplant(m,d); d.save(out)
        print('saved',out,len(d.getGlyphOrder()))
